command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: KLEMMENDE TÜR (Rondra) - Öffentlich
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined" || !DSK_FW.Zone) return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Klemmende Tür";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    // Framework-Wächter informieren
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("rondraKlemmendeTuer", finalEffektName, "Die Verklemmung der Tür/Luke löst sich auf, sie lässt sich nun wieder normal öffnen.");
    }

    // --- 2. CASTER & QS ERMITTELN ---
    let safeTestData = typeof testData !== "undefined" ? testData : null;
    let safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor = safeTestData?.actor || (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) || safeActor;
    if (!casterActor) casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;

    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) {
                casterActor = t.actor; break;
            }
        }
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qsWert = Number(safeTestData?.result?.QL || safeTestData?.qualityStep || casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // Fehlschlag-Karte (öffentlich)
    if (qsWert <= 0) {
        return ChatMessage.create({
            speaker: { alias: "System" },
            content: `${DSK_FW.UI.Header(gabenName, iconBild)}<div class="dskbox2"><p style="color:#B30000;text-align:center;"><b>Fehlschlag!</b></p></div>`
        });
    }

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

    // --- 3. SCHABLONE PLATZIEREN (0.5x0.5 Fläche) ---
    const confirmPosition = async () => {
        return await foundry.applications.api.DialogV2.wait({
            window: { title: "Tür markieren" },
            position: { width: 420 },
            content: `
                <form>
                    <div style="font-family: 'Signika', sans-serif;">
                        ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:0.95em; line-height:1.35;">Verschiebe die Markierung passgenau auf die Tür, Luke oder den Deckel.<br><br>Klicke danach auf <b>Position Bestätigen</b>.</p>
                        </div>
                    </div>
                </form>
            `,
            buttons: [
                { action: "ok", label: "Position Bestätigen", icon: "fas fa-check", default: true, callback: () => true },
                { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }
            ],
            rejectClose: false
        });
    };

    ui.notifications.info("Luna sagt 🌙: Platziere die Markierung auf der Tür.");

    const templateData = {
        t: "rect",
        user: game.user.id,
        distance: 0.7, 
        direction: 45,
        x: casterToken.center.x,
        y: casterToken.center.y,
        fillColor: "#76301b", // Edles Rondra-Rot
        fillAlpha: 0.5,
        lineThickness: 2,
        hidden: false,
        flags: { dsk: { isZoneSource: true } }
    };

    const createdTemplates = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [templateData]);
    let templateDoc = createdTemplates[0];

    try { canvas.templates.activate(); } catch (e) {}
    const isConfirmed = await confirmPosition();
    try { canvas.tokens.activate(); } catch (e) {}

    if (!isConfirmed || isConfirmed === false) {
        await templateDoc.delete();
        return ui.notifications.warn("Luna sagt 🌙: Markierung abgebrochen.");
    }

    let template = canvas.scene.templates.get(templateDoc.id);

    // --- 4. BERECHNUNGEN & FLAGS AUFRÄUMEN ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");
    await template.setFlag("dsk", "isZoneSource", true);

    const dauerMinuten = qsWert * 5;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const qsCalc = `<span ${thinStyle}>(${qsWert} QS x 5)</span>`;
    const dauerText = `${dauerMinuten} Minuten ${qsCalc}`;

    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    // --- 5. EFFEKT ANLEGEN (inkl. Framework-Bindung) ---
    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { minutes: dauerMinuten },
        description: `Die Tür/Luke wurde blockiert und lässt sich auch mit Gewalt nicht öffnen.`,
        flags: { 
            dsk: { 
                isZoneSource: true, 
                templateId: template.id, 
                radarTitel: gabenName, 
                ahne: ahne 
            } 
        }
    }]);

    // --- 6. ÖFFENTLICHE CHAT-KARTE SENDEN ---
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> verklemmt eine Tür, Luke oder einen Deckel mit eiserner göttlicher Kraft.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px; font-size: 0.9em;">
                    • Die blockierte Öffnung lässt sich während der Wirkungsdauer <b>auch mit Gewalt nicht mehr öffnen</b>.<br>
                    • Es ist jedoch weiterhin möglich, die Tür zu <b>zerstören</b>, um sich einen Durchgang zu schaffen.
                </p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerText}</p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        // Die Karte updaten (falls Kosten-Makro verknüpft war)
        await msg.update({ content: successContent }); // Whisper hier ebenfalls entfernt!
    } else {
        // Neu erstellen, ganz öffentlich
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
